category_columns = {}
for col in ws.iter_cols(min_col=2, max_col=19, min_row=5, max_row=5):
    for cell in col:
        if cell.value:
            category_columns[cell.value] = cell.column

# Create a dictionary to map brands to their rows in the source sheet
brand_rows = {}
for row in ws.iter_rows(min_row=6, max_row=19, min_col=1, max_col=1):
    for cell in row:
        if cell.value:
            brand_rows[cell.value] = cell.row

# Create a dictionary to map categories to their column indices in the destination sheet
destination_category_columns = {}
for col in ws.iter_cols(min_col=18, max_col=19, min_row=5, max_row=5):
    for cell in col:
        if cell.value:
            destination_category_columns[cell.value] = cell.column

# Fill the destination range with data
for row in range(6, 12):  # Rows 6 to 11
    brand = ws.cell(row=row, column=1).value
    if brand not in brand_rows:
        continue
    brand_row = brand_rows[brand]

    for col in range(2, 20):  # Columns B to T
        category = ws.cell(row=5, column=col).value
        if category not in category_columns:
            continue
        source_col = category_columns[category]
        source_cell = ws.cell(row=brand_row, column=source_col)
        value = source_cell.value if source_cell.value is not None else 0

        # Find the destination column for the category
        dest_col = destination_category_columns.get(category, None)
        if dest_col is not None:
            dest_cell = ws.cell(row=row, column=dest_col)
            dest_cell.value = value

# Save the workbook
wb.save('output.xlsx')
