# Load the workbook
wb = load_workbook('input.xlsx')
cover_sheet = wb['COVER']
data_sheet = wb['DATA']

# Get the entity from cell B12
entity = cover_sheet['B12'].value

# Find the row in the DATA sheet that corresponds to the entity
entity_row = None
for row in data_sheet.iter_rows(min_row=1, max_row=data_sheet.max_row, min_col=1, max_col=data_sheet.max_col):
    if row[0].value == entity:
        entity_row = row
        break

# Find the column headers in the DATA sheet
headers = data_sheet[1]

# Find the column indices for the required headers
col_index = {}
for idx, header in enumerate(headers):
    if header.value in ['Total', 'January', '% age', 'YTD']:
        col_index[header.value] = idx

# Find the column indices for the required columns
col_index['V - 6666'] = None
col_index['D - 1111'] = None
col_index['D - 2222'] = None
col_index['D - 3333'] = None

for idx, header in enumerate(headers):
    if header.value == 'V - 6666':
        col_index['V - 6666'] = idx
    elif header.value == 'D - 1111':
        col_index['D - 1111'] = idx
    elif header.value == 'D - 2222':
        col_index['D - 2222'] = idx
    elif header.value == 'D - 3333':
        col_index['D - 3333'] = idx

# Get the values for the entity row
values = []
for col in ['Total', 'January', '% age', 'YTD', 'V - 6666', 'D - 1111', 'D - 2222', 'D - 3333']:
    if col in col_index:
        values.append(entity_row[col_index[col]].value)

# Round the values to two decimal places
rounded_values = []
for value in values:
    if value is not None:
        if value < 0 and abs(value) < 0.01:
            rounded_values.append(0.00)
        else:
            rounded_values.append(round(value, 2))
    else:
